// Real project media, not fabricated screenshots. Captures are generated by the
// verified public-page recording workflow. Diagrams are explicitly labeled.
(() => {
  'use strict';
  const script = document.querySelector('script[src$="media.js"]');
  if (!script) return;
  const root = new URL('./', script.src);
  const asset = path => new URL(path, root).href;
  const url = asset('assets/project-media/manifest.json');
  const kindLabel = kind => kind === 'public-screen' ? 'Recorded public website / unauthenticated' :
    kind === 'simulator-render' ? 'Captured from actual simulator viewer / manual run' :
    'Repository-based technical illustration / not a screen recording';

  function showCard(card, media) {
    const art = card.querySelector('.work-art');
    if (!art || !media?.image || media.kind === 'source-diagram') return;
    const img = document.createElement('img');
    img.className = 'recorded-art';
    img.loading = 'lazy';
    img.decoding = 'async';
    img.alt = 'Captured view of ' + (card.querySelector('h3')?.textContent?.trim() || 'project');
    img.addEventListener('load', () => {
      art.classList.add('with-recorded-art');
      const tag = document.createElement('span');
      tag.className = 'recorded-corner';
      tag.textContent = 'ACTUAL ' + (media.kind === 'public-screen' ? 'SITE CAPTURE' : 'VIEWER RENDER');
      art.appendChild(tag);
    });
    img.addEventListener('error', () => img.remove());
    img.src = asset(media.image);
    art.appendChild(img);
    if (media.video) {
      const bottom = card.querySelector('.project-bottom');
      if (bottom) {
        const link = document.createElement('a');
        link.href = asset(media.video);
        link.className = 'clip-link';
        link.textContent = 'Watch recording ↗';
        link.target = '_blank';
        link.rel = 'noopener noreferrer';
        bottom.appendChild(link);
      }
    }
  }

  function showCase(slot, media) {
    if (!media?.image) return;
    const label = kindLabel(media.kind);
    const frame = document.createElement('div');
    frame.className = 'media-frame';
    const img = document.createElement('img');
    img.src = asset(media.image);
    img.loading = 'lazy';
    img.alt = media.kind === 'source-diagram' ?
      'Source-grounded visual explanation of project architecture' :
      'Visual recorded from the project identified in the case study';
    frame.appendChild(img);
    const intro = document.createElement('p');
    intro.className = 'media-title';
    intro.textContent = 'Project visuals / ' + (media.kind === 'source-diagram' ? 'technical diagram' : 'authentic capture');
    const caption = document.createElement('p');
    caption.className = 'media-caption';
    const strong = document.createElement('strong');
    strong.textContent = label + '. ';
    caption.append(strong, document.createTextNode(media.description || ''));
    slot.append(intro, frame, caption);
    if (media.video) {
      const videoSection = document.createElement('div');
      videoSection.className = 'media-video';
      const title = document.createElement('p');
      title.className = 'media-video-label';
      title.textContent = 'SHORT VIDEO WALKTHROUGH / PLAY ON DEMAND';
      const video = document.createElement('video');
      video.controls = true;
      video.playsInline = true;
      video.preload = 'none';
      video.poster = asset(media.image);
      video.setAttribute('aria-label', 'Recorded visual walkthrough for this project');
      const source = document.createElement('source');
      source.src = asset(media.video);
      source.type = 'video/webm';
      video.appendChild(source);
      videoSection.append(title, video);
      slot.appendChild(videoSection);
    }
    const extras = document.createElement('div');
    extras.className = 'media-extras';
    if (media.source) {
      const link = document.createElement('a');
      link.href = media.source;
      link.target = '_blank';
      link.rel = 'noopener noreferrer';
      link.textContent = media.kind === 'public-screen' ? 'Open the public website ↗' : 'View the project source ↗';
      extras.appendChild(link);
    }
    slot.appendChild(extras);
    slot.hidden = false;
  }

  fetch(url, { cache: 'no-cache' })
    .then(response => { if (!response.ok) throw new Error('Media manifest not available'); return response.json(); })
    .then(manifest => {
      const items = manifest.projects || {};
      document.querySelectorAll('[data-media-project]').forEach(card => {
        showCard(card, items[card.dataset.mediaProject]);
      });
      document.querySelectorAll('[data-visual-project]').forEach(slot => {
        showCase(slot, items[slot.dataset.visualProject]);
      });
    })
    .catch(() => { /* Existing illustrated project cards remain usable. */ });
})();
